import unittest
from candidate import derivative

class TestPolynomialDerivative(unittest.TestCase):
    def test_derivative_normal_case(self):
        self.assertEqual(derivative([3, 1, 2, 4, 5]), [1, 4, 12, 20])

    def test_derivative_single_term(self):
        self.assertEqual(derivative([1]), [])

    def test_derivative_linear_term(self):
        self.assertEqual(derivative([1, 2]), [2])

    def test_derivative_constant_term(self):
        self.assertEqual(derivative([5]), [])

    def test_derivative_with_floats(self):
        self.assertAlmostEqual(derivative([1.5, 2.5, 3.5]), [2.5, 10.5])

    def test_derivative_negative_coefficients(self):
        self.assertEqual(derivative([-1, -2, -3]), [-2, -6])

    def test_derivative_boundary_zero_coefficients(self):
        self.assertEqual(derivative([0, 0, 1, 2]), [0, 2])

    def test_derivative_empty_list(self):
        with self.assertRaises(TypeError):
            derivative([])

    def test_derivative_none_input(self):
        with self.assertRaises(TypeError):
            derivative(None)

    def test_derivative_non_list_input(self):
        with self.assertRaises(TypeError):
            derivative("invalid_input")

    def test_derivative_insufficient_length(self):
        with self.assertRaises(IndexError):
            derivative([1, 2, 3, 4, 5, 6][:2])

    def test_derivative_mixed_types(self):
        with self.assertRaises(TypeError):
            derivative([1, "2", 3])

    def test_derivative_high_order_terms(self):
        self.assertEqual(derivative([1, 2, 3, 4, 5, 6, 7]), [2, 6, 12, 20, 30])
